#[inline]
pub fn try_div2(a: &[u32], p: &[u32], out: &mut [u32]) -> bool {
    if a.len() == 12 && p == crate::params::p384::P {
        unsafe {
            nistp_div2_12(out.as_mut_ptr(), a.as_ptr());
        }
        true
    } else {
        false
    }
}

